"""Build the student's static website. No encoded source or remote executable code.
Inputs: the readable prompt log and attributed photo artifact from this repository.
Outputs: five HTML pages, local graph media, attribution, and a link-check report.
"""
from pathlib import Path
from html import escape
from html.parser import HTMLParser
from urllib.parse import urlsplit, unquote
import json
import re
import shutil
import subprocess

ROOT = Path.cwd()
GRAPH = ROOT / 'graph'
GRAPH.mkdir(exist_ok=True)
ASSETS = ROOT / 'photo-assets'
manifest = json.loads((ASSETS / 'photo-manifest.json').read_text())
photo_specs = [
    ('campus-0.jpg', 'tcu-campus.jpg', '慈濟大學校園建築', '2014 年歷史實拍；非目前經管系館照片。'),
    ('campus-1.jpg', 'tcu-library.jpg', '慈濟大學圖書館入口', '2014 年歷史實拍；非本系專屬教室。'),
    ('study-0.jpg', 'digital-learning.jpg', '數位學習情境', '授權情境攝影；非本系課堂或研究系統畫面。'),
    ('circular-1.jpg', 'circular-nature.jpg', '黑水虻主題攝影', '黑水虻成蟲自然攝影；非該團隊的幼蟲材料或研究現場。')
]
class PlainText(HTMLParser):
    def __init__(self):
        super().__init__(); self.parts = []
    def handle_data(self, data):
        self.parts.append(data)
def strip_tags(value):
    p = PlainText(); p.feed(value); return ''.join(p.parts).strip()
credits = []
for original, target, title, context in photo_specs:
    item = next(x for x in manifest if x['file'] == original)
    meta = item['metadata']
    license_name = meta['LicenseShortName']['value']
    assert license_name in ('CC BY-SA 4.0', 'CC0 1.0', 'CC0'), license_name
    shutil.copyfile(ASSETS / original, GRAPH / target)
    credits.append(dict(file='graph/' + target, title=title, context=context,
        author=strip_tags(meta['Artist']['value']), source=item['descriptionurl'],
        license=license_name, license_url=meta['LicenseUrl']['value'],
        date=meta.get('DateTimeOriginal', {}).get('value', ''),
        changes='照片檔沿用來源縮圖；網頁以 CSS 裁切。照片剪輯片有縮放與編排；CC BY-SA 素材及其改作依相同授權提供。'))

