def header(current):
    links = [('index.html','系所簡介'),('studentworks.html','學生作品'),('index.html#learning','學習特色'),('index.html#resources','系所資源'),('ai-collaboration.html','製作紀錄'),('#contact','聯絡我們')]
    nav = ''.join('<a href="'+url+'"'+(' aria-current="page"' if current==url else '')+'>'+label+'</a>' for url,label in links)
    return '''<a class="skip" href="#main">跳到主要內容</a><div class="topline"><div class="wrap"><span>慈濟大學 / 智慧永續管理學院</span><div class="toplinks"><a href="https://www.tcu.edu.tw/" target="_blank" rel="noopener noreferrer">慈大首頁 ↗</a><a href="https://mdm.tcu.edu.tw/" target="_blank" rel="noopener noreferrer">官方公告 ↗</a></div></div></div><header class="header"><div class="wrap"><div class="brandrow"><a class="brand" href="index.html" aria-label="慈濟大學經營管理學系，回首頁"><span class="mark" aria-hidden="true">TCU</span><span><small>慈濟大學</small><strong>經營管理學系</strong></span></a><span class="university">TZU CHI UNIVERSITY</span><button class="menu" aria-expanded="false" aria-controls="nav" type="button">選單 ☰</button></div><nav class="nav" id="nav" aria-label="主要導覽">'''+nav+'</nav></div></header>'

