def page(filename,title,body,script=''):
    text='<!doctype html>\n<html lang="zh-Hant-TW"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#8b1e2d"><meta name="description" content="慈濟大學經營管理學系學生網站設計提案。系所介紹、學習特色、學生作品及 AI 協作紀錄。"><title>'+escape(title)+'｜慈濟大學經營管理學系</title><style>'+CSS+'</style></head><body id="top" data-site-version="tcu-public-photo-20261022">'+header(filename)+'<main id="main">'+body+'</main>'+FOOTER+'<script>'+NAV_JS+script+'</script></body></html>'
    (ROOT/filename).write_text(text,encoding='utf-8')

