def card(w,details=False):
    link='#'+w['id'] if details else 'studentworks.html#'+w['id']
    extra=('''<details><summary>閱讀作品介紹 ＋</summary><p><strong>'''+escape(w['full'])+'</strong></p><p>'+escape(w['detail'])+'</p><a class="link" href="'+escape(w['source'],quote=True)+'" target="_blank" rel="noopener noreferrer">閱讀系網原始公告 ↗</a></details>') if details else ''
    return '<article class="card" id="'+w['id']+'" data-category="'+w['category']+'" data-search="'+escape(w['title']+' '+w['full']+' '+w['tags'],quote=True)+'"><a class="card-image" href="'+link+'"><img src="graph/'+w['image']+'" alt="'+w['alt']+'" width="1000" height="606" loading="lazy"><span class="badge">'+w['badge']+'</span></a><div class="meta"><span>'+w['category']+'</span><span>'+w['year']+'</span></div><h3><a href="'+link+'">'+w['title']+'</a></h3><p class="card-description">'+w['desc']+'</p><div class="card-bottom"><span>'+w['tags']+'</span><a href="'+escape(w['source'],quote=True)+'" target="_blank" rel="noopener noreferrer">原始公告 ↗</a></div>'+extra+'<p class="fine">'+w['credit']+' <a href="photo-credits.html">來源說明</a></p></article>'

home='''<section class="hero wrap"><div><p class="kicker">以人為本的經營管理</p><p class="eyebrow">DEPARTMENT OF BUSINESS MANAGEMENT</p><h1>理解商業，<br><span class="red">創造改變。</span></h1><p class="hero-description">以人文為起點，讓商管專業回應世界。從市場洞察、數位應用到永續經營，將課堂裡的想法，轉化為理解問題與付諸實踐的能力。</p><div class="actions"><a class="button" href="#about">認識經管系 ↗</a><a class="link" href="studentworks.html">探索學生作品 →</a></div><p class="hero-note">OUR PERSPECTIVE<br>把人，放在每一次決策的中心。</p></div><figure class="hero-photo"><img src="graph/tcu-campus.jpg" alt="慈濟大學校園建築，2014 年實拍；非目前經管系館。" width="1600" height="1067" fetchpriority="high"><figcaption>慈濟大學校園｜Cerevisae，2014 年實拍 · CC BY-SA 4.0<br>歷史影像，不代表目前經管系館現況。<a href="photo-credits.html">照片來源與說明</a></figcaption></figure></section>
<section class="section wash" id="about"><div class="wrap"><div class="heading"><div><p class="eyebrow">01 / ABOUT THE DEPARTMENT</p><h2>專業有深度，<br>經營有溫度。</h2></div><div class="intro"><p>經營管理，不只是理解企業如何運作，也是在每一次選擇中，看見人與社會的需要。</p><p>本系重視人文與職場倫理、創意思考、團隊合作及跨文化視野，連結商管學習與實務應用。</p><a class="link" href="https://mdm.tcu.edu.tw/p/412-1021-2.php?Lang=zh-tw" target="_blank" rel="noopener noreferrer">認識本系教育方向 ↗</a></div></div><div class="values">
<article><span class="value-n">01</span><h3>人文素養</h3><p>從尊重與倫理出發，思考專業的責任。</p><small>HUMANITY</small></article><article><span class="value-n">02</span><h3>創意思考</h3><p>提出不同的問題，探索更好的可能。</p><small>CREATIVITY</small></article><article><span class="value-n">03</span><h3>團隊合作</h3><p>在溝通與協作之間，完成共同目標。</p><small>COLLABORATION</small></article><article><span class="value-n">04</span><h3>跨文化視野</h3><p>理解差異，培養與世界對話的能力。</p><small>GLOBAL PERSPECTIVE</small></article></div></div></section>
<section class="section" id="learning"><div class="wrap learning"><figure class="learning-photo"><img src="graph/tcu-library.jpg" alt="慈濟大學圖書館入口，2014 年歷史實拍。" width="1600" height="1067" loading="lazy"><figcaption>LEARN WITH PURPOSE. 慈濟大學圖書館入口，2014 年<br>Cerevisae · CC BY-SA 4.0 · <a href="photo-credits.html">照片來源</a></figcaption></figure><div><p class="eyebrow">02 / LEARNING EXPERIENCE</p><h2>把教室，延伸到<br>真實世界。</h2><p class="hero-description">從理解概念、練習方法，到走進場域，讓知識成為能夠運用的能力。</p><div class="accordion"><details open><summary>01　商管知識，連結多元應用</summary><p>從市場與行銷、流通服務、電子商務到永續經營，探索商業問題的不同面向。<br><a class="link" href="https://mdm.tcu.edu.tw/p/412-1021-16.php?Lang=zh-tw" target="_blank" rel="noopener noreferrer">查看各入學年度課規 ↗</a></p></details><details><summary>02　在實務場域練習與反思</summary><p>透過個案討論、簡報溝通及場域學習，把理解轉化為實際方法。圖書館照片不是本系專屬教室。<br><a class="link" href="https://mdm.tcu.edu.tw/p/412-1021-2.php?Lang=zh-tw" target="_blank" rel="noopener noreferrer">認識本系教學特色 ↗</a></p></details><details><summary>03　讓專題與實習走向產業</summary><p>透過專題、實習與跨域學習，累積發現問題、整合資訊及提出方案的經驗。<br><a class="link" href="https://mdm.tcu.edu.tw/p/412-1021-5007.php?Lang=zh-tw" target="_blank" rel="noopener noreferrer">前往學生實習專區 ↗</a></p></details></div><p class="fine" style="margin-top:18px">學習方向依官方公開介紹整理；實際課程與實習安排，以各年度公告為準。</p></div></div></section>
<section class="section wash"><div class="wrap"><div class="heading"><div><p class="eyebrow">03 / IDEAS IN ACTION</p><h2>讓作品，<br>說出學習的故事。</h2></div><div class="intro"><p>不只停留在想法，也在真實議題中留下學習的足跡。</p><a class="link" href="studentworks.html">瀏覽全部學生作品 ↗</a></div></div><div class="projects">'''+''.join(card(w) for w in works[:2])+'''</div></div></section>
<section class="section" id="resources"><div class="wrap"><div class="heading"><div><p class="eyebrow">04 / YOUR NEXT STEP</p><h2>找到你的下一步。</h2></div><p class="intro">給準備認識經管的你，也給正在累積專業的你。</p></div><div class="resources">'''+''.join('<a class="resource" href="https://mdm.tcu.edu.tw/p/412-1021-'+code+'.php?Lang=zh-tw" target="_blank" rel="noopener noreferrer"><span>'+en+' ↗</span><h3>'+zh+'</h3><p>'+desc+'</p></a>' for en,zh,desc,code in [('FACULTY','師資介紹','認識教師的專業領域','4505'),('CURRICULUM','課程規畫','查閱各年度課程規範','16'),('INTERNSHIP','實習資訊','了解實務學習相關資訊','5007'),('ADMISSIONS','招生管道','前往官方招生資訊專區','63')])+'''</div></div></section>'''
page('index.html','系所簡介',home)

student='''<section class="works-hero wrap"><div><p class="breadcrumb"><a href="index.html">首頁</a> / 學生作品</p><p class="eyebrow">STUDENT WORK / IDEAS IN ACTION</p><h1>從想法出發，<br><span class="red">讓學習被看見。</span></h1><p class="hero-description">探索學生如何把商管方法、數位工具與永續思考，轉化成研究及創新提案。作品資訊依公開公告整理，不將主題攝影冒稱為學生實拍。</p><a class="link" href="#collection" style="margin-top:25px">瀏覽作品集 ↓</a></div><figure class="spotlight"><img src="graph/circular-nature.jpg" alt="黑水虻成蟲主題攝影，並非本系實驗材料或研究現場。" width="1000" height="606"><figcaption><p class="eyebrow">FEATURED / CIRCULAR ECONOMY</p><h2>讓廢棄物有新的可能</h2><p class="fine">以黑水虻處理沼渣的可行性研究。</p><a class="link" href="#circular">閱讀作品 ↓</a></figcaption></figure></section>
<section class="section wash" id="collection"><div class="wrap"><div class="heading"><div><p class="eyebrow">THE COLLECTION</p><h2>每個問題，都是起點。</h2></div><p class="intro">從研究題目與公開成果，認識學生的探索方向。</p></div><div class="tools"><div class="filters" aria-label="作品類別"><button type="button" data-filter="全部" aria-pressed="true">全部作品</button><button type="button" data-filter="永續實踐" aria-pressed="false">永續實踐</button><button type="button" data-filter="數位應用" aria-pressed="false">數位應用</button></div><label><span class="sr-only">搜尋作品名稱或主題</span><input class="search" id="search" type="search" placeholder="搜尋作品名稱或主題" aria-label="搜尋作品名稱或主題"></label></div><p class="result" id="result" aria-live="polite">共 3 件作品</p><div class="projects" id="projects">'''+''.join(card(w,True) for w in works)+'''</div><p class="empty" id="empty" hidden>沒有符合的作品，請換個關鍵字或選擇其他類別。</p><noscript><p class="fine">目前顯示全部作品；啟用 JavaScript 後可使用搜尋與篩選。</p></noscript></div></section>
<section class="section"><div class="wrap"><div class="heading"><div><p class="eyebrow">PHOTOGRAPHY / LEARNING IN FOCUS</p><h2>用影像，記錄學習的現場。</h2></div><p class="intro">為後續課程的自行拍攝作品預留位置。此區尚未上傳學生實拍，不以授權素材代替攝影作業。</p></div><div class="photo-grid">'''+''.join('<figure class="photo-slot"><div class="photo-frame" aria-hidden="true">'+num+'</div><figcaption><p class="fine">待補自行拍攝作品</p><h3>'+title+'</h3><p>'+desc+'</p><p class="fine">拍攝者、日期及作品說明：待完成</p></figcaption></figure>' for num,title,desc in [('01','課堂討論','記錄觀點交流與團隊合作的片刻。'),('02','場域觀察','從真實環境尋找值得探索的問題。'),('03','專題發表','呈現研究、練習與成果分享。')])+'''</div></div></section>
<section class="section wash"><div class="wrap"><div class="heading"><div><p class="eyebrow">MOVING IMAGES</p><h2>讓故事，有更多表達方式。</h2></div></div><div class="media"><video controls preload="metadata" playsinline poster="graph/tcu-campus.jpg"><source src="graph/learning-intro.mp4" type="video/mp4"><p>瀏覽器不支援影片，請<a href="graph/learning-intro.mp4">開啟 MP4</a>。</p></video><div><p class="eyebrow">PHOTO ESSAY / WEBSITE DEMONSTRATION</p><h3>學習，從觀察開始。</h3><p>16 秒無聲照片剪輯示範，展示校園、閱讀與主題探索的影像編排。這不是活動實錄，也不是使用者自行拍攝的課程影片。</p><p class="fine" style="margin-top:20px">4 張授權照片 / 960 × 540 / MP4<br>照片及影片中的 BY-SA 改作素材依 CC BY-SA 4.0 提供。<a href="photo-credits.html">作者與素材來源</a></p><details><summary>影片文字說明</summary><p>0–4 秒：慈大校園建築（2014）。4–8 秒：慈大圖書館入口（2014）。8–12 秒：電腦與閱讀情境。12–16 秒：黑水虻成蟲主題攝影。全部為照片剪輯，沒有旁白或音樂。</p></details></div></div></div></section><section class="closing"><div class="wrap"><p class="eyebrow">CONTINUE EXPLORING</p><h2>作品之外，還有更多可能。</h2><p class="muted">認識我們的學習方向，找到下一段探索的起點。</p><a class="button" href="index.html">返回系所簡介 →</a></div></section>'''
filter_js='''const search=document.getElementById('search'),cards=[...document.querySelectorAll('#projects .card')],filters=[...document.querySelectorAll('[data-filter]')];let category='全部';function apply(){const term=search.value.trim().toLocaleLowerCase();let count=0;cards.forEach(c=>{const ok=(category==='全部'||c.dataset.category===category)&&c.dataset.search.toLocaleLowerCase().includes(term);c.hidden=!ok;if(ok)count++});document.getElementById('result').textContent='共 '+count+' 件作品';document.getElementById('empty').hidden=count!==0}filters.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;filters.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));apply()}));search.addEventListener('input',apply);'''
page('studentworks.html','學生作品',student,filter_js)

log=(ROOT/'AI-COLLABORATION-FULL.txt').read_text(encoding='utf-8-sig')
chunks=re.split(r'(?m)^={20,}\n(?=第 \d+ 則)',log)[1:]
assert len(chunks)==12, 'Expected all 12 actual user prompts'
record_cards=[]
for chunk in chunks:
    title=chunk.splitlines()[0]
    match=re.search(r'Prompt（原文開始）：\n(.*?)\n（原文結束）',chunk,re.S)
    assert match, title
    note=chunk.split('後補筆記（供本人確認）：',1)[-1].strip()
    record_cards.append('<details><summary>'+escape(title)+'</summary><pre>'+escape(match.group(1))+'</pre><p>後補筆記（供本人確認）：'+escape(note)+'</p></details>')
record='''<section class="section"><div class="wrap record"><p class="breadcrumb"><a href="index.html">首頁</a> / AI 協作與製作紀錄</p><p class="eyebrow">PROCESS / AI COLLABORATION</p><h1>把需求、設計與修正，<br><span class="red">留下完整紀錄。</span></h1><p class="hero-description">本頁保留這次系網工程師對話中的 12 則實際使用者 Prompt。教師範例包含在原訊息內，不虛列為另外執行的指令；後補筆記不是當時原始心得，請本人確認後繳交。</p><div class="record-tools"><button id="expand" type="button">展開全部紀錄</button><button id="collapse" type="button">收合全部紀錄</button><a class="button" href="AI-COLLABORATION-FULL.txt" download>下載完整 TXT ↓</a></div>'''+''.join(record_cards)+'''<section class="section"><p class="eyebrow">DESIGN & RESPONSIBILITY</p><h2>參考架構，不複製身分。</h2><p class="hero-description">內容以慈濟經管公開介紹與成果公告為依據，參考哈佛經濟系的學術資訊層級，採用深紅、黑白、留白與襯線標題。未移植哈佛校徽、人物或研究成果。</p><p class="hero-description">AI 協助網站架構、程式、版面、檔案檢查及照片來源整理；使用者提出系所定位、刪修要求、風格方向與評分標準。自行拍攝作業、最終內容確認與老師評分不由 AI 代替。</p><div class="table-wrap"><table><thead><tr><th>要求</th><th>實作位置</th></tr></thead><tbody><tr><td>首頁與作品頁</td><td>index.html、studentworks.html</td></tr><tr><td>所有圖片與影片</td><td>graph/，頁面使用相對路徑</td></tr><tr><td>跨頁導覽</td><td>每頁頂部與頁尾</td></tr><tr><td>正式風格與後續影像</td><td>學術版型、攝影預留區、影片播放器</td></tr><tr><td>AI 協作</td><td>12 則 Prompt、完整 TXT、後補筆記</td></tr><tr><td>公開上線</td><td>GitHub main 分支；以 Pages 實際發布結果驗收，不預先宣稱已成功</td></tr></tbody></table></div><p class="fine" style="margin-top:20px">檔案結構檢查見 <a href="WEBSITE-TESTS.json">WEBSITE-TESTS.json</a>；照片來源見 <a href="photo-credits.html">授權頁面</a>。檔案檢查不等於公開網站已完成部署。</p></section></div></section>'''
record_js="document.getElementById('expand').onclick=()=>document.querySelectorAll('.record details').forEach(d=>d.open=true);document.getElementById('collapse').onclick=()=>document.querySelectorAll('.record details').forEach(d=>d.open=false);"
page('ai-collaboration.html','AI 協作與製作紀錄',record,record_js)
credit_cards=[]
