# Verify all on-site paths and fragment targets. External sites are not asserted here.
class LinkCheck(HTMLParser):
    def __init__(self):
        super().__init__();self.links=[];self.ids=set();self.media=[]
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a:self.ids.add(a['id'])
        for key in ('href','src','poster'):
            if key in a:self.links.append((tag,key,a[key]))
        if tag in ('img','video','source'):
            self.media.extend(a[k] for k in ('src','poster') if k in a)
parsers={}
for name in ['index.html','studentworks.html','ai-collaboration.html','photo-credits.html','404.html']:
    p=LinkCheck();p.feed((ROOT/name).read_text());parsers[name]=p
errors=[];checked=0
for name,p in parsers.items():
    for media in p.media:
        if not media.startswith('graph/'):errors.append('Non-graph media: '+name+' '+media)
    for tag,key,link in p.links:
        u=urlsplit(link)
        if u.scheme or u.netloc:continue
        path=unquote(u.path).lstrip('/') or name
        if not (ROOT/path).is_file():errors.append('Missing path: '+name+' '+path)
        if u.fragment and path in parsers and u.fragment not in parsers[path].ids:errors.append('Missing anchor: '+name+' '+link)
        checked+=1
assert not errors, '\n'.join(errors)
probe=json.loads(subprocess.check_output(['ffprobe','-v','quiet','-show_format','-show_streams','-of','json',str(GRAPH/'learning-intro.mp4')]))
report={'version':'tcu-public-photo-20261022','html_pages':list(parsers),'relative_links_checked':checked,'errors':errors,'prompt_count':len(chunks),'video_seconds':float(probe['format']['duration']),'video_width':probe['streams'][0]['width'],'video_height':probe['streams'][0]['height'],'all_images_and_video_in_graph':True,'public_http_verification':'Separate deployment check required.','visual_browser_test':'Not performed by this build script.'}
(ROOT/'WEBSITE-TESTS.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
